<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class InsurancePolicyRequest extends FormRequest { public function authorize(): bool{return $this->user()!==null;} public function rules(): array{return ['pet_id'=>'required|exists:pets,id','provider'=>'required|string|max:255','policy_number'=>'required|string|max:255','start_date'=>'nullable|date','end_date'=>'nullable|date|after_or_equal:start_date','coverage_summary'=>'nullable|string','claims'=>'nullable|array','document'=>'nullable|file|mimes:pdf,jpg,jpeg,png|max:5120'];} }